static int u1(byte[] data, int off) {
    return data[off] & 0xFF;
}

static int u2(byte[] data, int off) {
    return ((data[off] & 0xFF) << 8)
         |  (data[off + 1] & 0xFF);
}

static long u4(byte[] data, int off) {
    return ((long) u2(data, off) << 16) | u2(data, off + 2);
}

byte[] bytes = Files.readAllBytes(Paths.get("Hello.class"));
long magic = u4(bytes, 0);
int minor = u2(bytes, 4);
int major = u2(bytes, 6);
int cpCount = u2(bytes, 8);

System.out.println(Long.toHexString(magic)); // cafebabe
System.out.println(major); // Java 8 -> 52

